#!/usr/bin/env python3
import json,collections
from pathlib import Path
R=Path(__file__).resolve().parents[2];P=R/'cross_platform'
read=lambda p:json.loads(p.read_text())
design=read(R/'checklist/task1_design.json');issues=read(R/'task1/evidence/issues.json');bugs={cid:i for i in issues for cid in i['cases']}
runs={b:read(P/f'evidence/{b}.json') for b in ('chrome','firefox','android') if (P/f'evidence/{b}.json').exists()}
by={b:{r['id']:r for r in d['results']} for b,d in runs.items()};complete=len(runs)==3
md=['# Task 3 — Cross-browser / Cross-platform','','Sinh viên: **Phạm Quang Vinh — 23120202 — 23120202@student.hcmus.edu.vn**.','',f'**Trạng thái: {len(runs)}/3 nền tảng; '+('đã thực thi đủ ba nền tảng.**' if complete else 'chưa hoàn thành Task 3.**'),'','## Môi trường và kết quả','','| Trình duyệt | Máy / OS | Chạy | Passed | Failed | Bằng chứng |','|---|---|---|---|---|---|']
for b,d in runs.items():
 c=collections.Counter(r['status'] for r in d['results']);v=d['runs']['login']['browser'];env=d['environment']
 md.append(f'| {b} {v} | {env["device"]} / {env["os"]} | {len(d["results"])} | {c["Passed"]} | {c["Failed"]} | [JSON](evidence/{b}.json), [ảnh](screenshots/{b}/) |')
if not complete:md.append('| Nền tảng 3 | Chưa chạy | 0 | — | — | Not run |')
md+=['','Chrome desktop dùng bản Google Chrome cài trên laptop MSI Cyborg 15 A12VF/Ubuntu. Firefox 159.0 là bản Gecko thật do Playwright tải về (build v1573), chạy có cửa sổ; không phải thay user-agent Chrome. Firefox hệ thống 156.0.1 không được dùng trong lượt tự động này.','']
if 'android' in runs:
 s=read(P/'evidence/android_session.json');md += [f'Android chạy trên **Samsung Galaxy S23 thật (SM-S911B), Android {s["session"].get("os_version","13.0")}**, được BrowserStack cấp cho tài khoản Free. [Phiên BrowserStack]({s["session"].get("browser_url","")}) · [Metadata phiên](evidence/android_session.json).', '', 'Trạng thái session passed trên BrowserStack chỉ xác nhận script hoàn tất; 28 mục ứng dụng Failed vẫn được ghi đầy đủ trong JSON/Excel.','','BrowserStack Local kết nối thiết bị về EShop trên máy người làm bài; ảnh ghi URL localhost thật. User-agent Chrome bị rút gọn thành Android 10/K và version 149.0.0.0; OS Android 13.0 được xác nhận riêng bằng metadata phiên BrowserStack. Không dùng user-agent rút gọn để suy ra phiên bản OS.', '']
md+=['## Quy trình và tính xác thực của ảnh','','- Dùng 58 tiêu chí Task 1 đã duyệt; Login, Profile/Lịch sử đơn, Admin Orders; Home/navbar hỗ trợ thao tác.','- Mỗi lượt tạo dữ liệu task3-*; không thay bằng chứng hoặc fixture task1-* và không sửa source SUT.','- Desktop dùng viewport 1366×900; GUI-057 kiểm tra 360×800. Android giữ viewport do thiết bị cung cấp (ban đầu 360×649 CSS pixels, DPR 3), không ép thành desktop.','- Ảnh được chụp trực tiếp từ trình duyệt. Desktop chụp toàn trang với nhãn metadata ở cuối tài liệu. Android chụp vùng web trực tiếp từ Chrome, giới hạn theo visualViewport để tránh lỗi ghép ảnh khi trang tràn ngang; cuộn tới phần liên quan và đặt nhãn phía trên với khoảng đệm. Ảnh không bao gồm popup riêng của Chrome (lưu mật khẩu/thông báo khởi động). Ảnh màn hình thiết bị được dùng khi chẩn đoán, không thay thế ảnh bằng chứng cuối. Nhãn có email/MSSV/họ tên/browser/version/OS/device/URL/UTC, được thêm sau khi đo rồi gỡ ngay; không dựng lại UI hay sửa ảnh hậu kỳ.','- Form Hồ sơ fixture có Họ Tên = Phạm Quang Vinh — 23120202. Native alert được ghi text vào JSON rồi đóng; ảnh tương ứng là nền trang, không phải hộp thoại.','- GUI-036/037 dùng fault injection trì hoãn API/HTTP 500. Desktop trì hoãn 1800ms; Android giữ response đến sau khi đo/chụp để độ trễ cloud không làm mất trạng thái loading. GUI-013/016 dùng phím do automation gửi; trên Android đây là hỗ trợ bàn phím, không phải đánh giá bàn phím cảm ứng.','- Cho phép local-network-access riêng cho localhost:5173/5174 để Chrome kết nối BrowserStack Local. Android tap điều chỉnh theo visualViewport offset; GUI-057 so scrollWidth với visualViewport.width 360px vì layout viewport tự nới khi tràn ngang. Lỗi khởi tạo cloud hoặc timeout tự động hóa được sửa/tách khỏi lỗi SUT; không tính chúng thành Failed của ứng dụng.','',f'Tổng lượt kiểm tra: **{sum(len(d["results"]) for d in runs.values())}**. Tổng ảnh Failed: **{sum(r["status"]=="Failed" for d in runs.values() for r in d["results"])}**.','','## Đối chiếu 58 mục','','| ID | IA | Chrome | Firefox | Android Chrome | Bug / ảnh |','|---|---|---|---|---|---|']
comparison=[]
for item in design:
 cid=item['id'];states={b:by[b][cid]['status'] for b in runs};links=[]
 if cid in bugs:links.append(f'[{bugs[cid]["id"]}]({bugs[cid]["url"]})')
 for b in runs:
  if by[b][cid]['screenshot']:links.append(f'[ảnh {b}](screenshots/{b}/{cid}.png)')
 md.append('| '+' | '.join([cid,item['ia'],states.get('chrome','Not run'),states.get('firefox','Not run'),states.get('android','Not run'),' / '.join(links)])+' |')
 comparison.append({'id':cid,'statuses':states,'different_status':len(set(states.values()))>1})
diffs=[r for r in comparison if r['different_status']]
md+=['','## Khác biệt quan sát được','',f'Có **{len(diffs)} mục khác biệt Passed/Failed** giữa các lượt chạy. Kết quả chỉ áp dụng cho những môi trường và dữ liệu đã ghi.','']
for r in diffs:md.append(f'- {r["id"]}: '+', '.join(f'{b}={s}' for b,s in r['statuses'].items()))
md+=['','| Mục | Chrome | Firefox | Android |','|---|---|---|---|']
for cid in ('GUI-011','GUI-013','GUI-057'):
 vals=[by[b][cid]['actual'].replace('|',' / ').replace('\n','; ') if b in by else 'Not run' for b in ('chrome','firefox','android')];md.append('| '+cid+' | '+' | '.join(vals)+' |')
md+=['','Các lượt dùng ID đơn hàng tự tăng khác nhau. Số đo độ rộng là quan sát theo từng fixture, không chứng minh chênh lệch do riêng engine trình duyệt.','','Các lỗi cùng nguyên nhân ánh xạ vào Issues hiện có; không tạo báo cáo trùng chỉ vì cùng lỗi xuất hiện trên trình duyệt khác.','','## Chạy lại','','Từ HW03 root, sau khi backup SQLite và với các server :3000, :5173, :5174 đang chạy:','','```bash','python3 submission/cross_platform/scripts/run_platform.py chrome','python3 submission/cross_platform/scripts/run_platform.py firefox','node submission/cross_platform/scripts/run_browserstack_android.cjs','python3 submission/cross_platform/scripts/build_report.py','python3 submission/checklist/build_checklist.py','```','','Android cần tài khoản BrowserStack có quyền Automate/Android và BrowserStack Local. Runner dùng playwright-core 1.62.0 cùng browserstack-local trong ~/.cache/hw03-browserstack/runtime/node_modules, binary BrowserStackLocal trong ~/.cache/hw03-browserstack, và credentials.json riêng có username/access_key (quyền file 600). Thông tin xác thực nằm trong private cache của người dùng, không đưa vào repository. Không chạy song song các lượt vì dùng chung DB fixture. Không khởi động lại backend trước khi backup: database.js reset dữ liệu khi import.','','Tài liệu cấu hình: [BrowserStack Playwright Android](https://www.browserstack.com/docs/automate/playwright/playwright-android/nodejs), [Local Testing](https://www.browserstack.com/docs/automate/playwright/local-testing/introduction).','','Xác nhận duyệt trước đó áp dụng Task 1. Task 3 là các lượt chạy mới, ghi nhận bằng chứng thực tế và không giả định đã được duyệt lại.']
(P/'README.md').write_text('\n'.join(md)+'\n');(P/'evidence/comparison.json').write_text(json.dumps({'completed_platforms':list(runs),'required_platform_count':3,'status':'complete' if complete else 'incomplete','comparisons':comparison},ensure_ascii=False,indent=2)+'\n')
print('Platforms',len(runs),'differences',len(diffs))
